import { access, appendFile, mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import type { Model, ModelStatic } from 'sequelize';
import { config } from '../config.js';
import { db } from '../db/sequelize.js';
import { decrypt } from '../lib/crypto.js';
import { event } from './audit.js';
import { acquireBuildSlot } from './deploy-queue.js';
import { appDir, appHealth, compose, deploymentLogFile, srcDir, writeCompose } from './docker.js';
import { fetchSource } from './git.js';

// 07 §3–§7 — fetching → dockerfile resolution → generated files → build → up -d → health → live.
// Every printed line goes to the per-deployment log file AND the SSE hub (07 §8).
// The PAT is only ever passed to git.ts/compose redact lists (10 §7); headers print [REDACTED].

interface DeploymentInstance extends Model {
  id: string;
  appId: string;
  commitSha: string;
  commitMessage: string | null;
  author: string | null;
  branch: string;
  status: 'queued' | 'fetching' | 'building' | 'deploying' | 'live' | 'failed';
  error: string | null;
  startedAt: Date | null;
  finishedAt: Date | null;
}
interface AppInstance extends Model {
  id: string;
  slug: string;
  repoOwner: string;
  repoName: string;
  branch: string;
  port: number;
  healthcheckPath: string;
  buildType: 'auto' | 'dockerfile' | 'node' | 'static';
  accessTokenEnc: string | null;
  status: string;
}
interface EnvInstance extends Model {
  key: string;
  valueEnc: string;
}
const Deployments = db.Deployment as unknown as ModelStatic<DeploymentInstance>;
const Apps = db.App as unknown as ModelStatic<AppInstance>;
const EnvVars = db.EnvVar as unknown as ModelStatic<EnvInstance>;

const HEAD_SHA = '0'.repeat(40);
const logPath = deploymentLogFile;

// ---- deployment-log hub (06 §13): live SSE subscribers per deployment id
export type HubEvent =
  | { type: 'log'; line: string }
  | { type: 'status'; status: string }
  | { type: 'done'; status: string };

const listeners = new Map<string, Set<(e: HubEvent) => void>>();

export const subscribeDeploymentLog = (deploymentId: string, cb: (e: HubEvent) => void): (() => void) => {
  const set = listeners.get(deploymentId) ?? new Set();
  listeners.set(deploymentId, set);
  set.add(cb);
  return () => {
    set.delete(cb);
    if (set.size === 0) listeners.delete(deploymentId);
  };
};

// Streams stay open one turn past `done` only — the map entry is removed after it.
const emit = (deploymentId: string, e: HubEvent): void => {
  for (const cb of listeners.get(deploymentId) ?? []) {
    try {
      cb(e);
    } catch {
      /* a dead stream must never stall the pipeline */
    }
  }
};

export const tailDeploymentLog = async (deploymentId: string, count: number): Promise<string[]> => {
  try {
    const lines = (await readFile(logPath(deploymentId), 'utf8')).split('\n');
    if (lines[lines.length - 1] === '') lines.pop();
    return lines.slice(-count);
  } catch {
    return []; // no file yet = empty log (07 §8: the file is appended across all steps)
  }
};

// ---- 07 §4.1/§4.2 — resolution table and generated templates (pure, tested byte-exact)

export type BuildKind = 'dockerfile' | 'node' | 'static';

export const renderDockerfile = (kind: Exclude<BuildKind, 'dockerfile'>, port: number): string =>
  kind === 'node'
    ? `# generated by Swim — do not edit
FROM node:24-alpine
WORKDIR /app
COPY src/package*.json ./
RUN npm ci
COPY src/ ./
RUN npm run build --if-present
ENV NODE_ENV=production
USER node
EXPOSE ${port}
CMD ["npm", "start"]
`
    : `# generated by Swim — do not edit
FROM nginx:1-alpine
COPY src/ /usr/share/nginx/html
COPY .swim/nginx.conf /etc/nginx/conf.d/default.conf
EXPOSE ${port}
`;

export const renderStaticNginxConf = (port: number): string => `# generated by Swim — do not edit
server {
  listen ${port};
  root /usr/share/nginx/html;
  index index.html;
  location / {
    try_files $uri $uri/ /index.html;
  }
}
`;

const exists = (path: string): Promise<boolean> =>
  access(path).then(
    () => true,
    () => false,
  );

const hasStartScript = async (slug: string): Promise<boolean> => {
  try {
    const pkg = JSON.parse(await readFile(join(srcDir(slug), 'package.json'), 'utf8')) as { scripts?: Record<string, string> };
    return typeof pkg.scripts?.start === 'string';
  } catch {
    return false;
  }
};

export const resolveBuild = async (slug: string, buildType: AppInstance['buildType']): Promise<BuildKind> => {
  const hasDockerfile = await exists(join(srcDir(slug), 'Dockerfile'));
  if (buildType === 'dockerfile') {
    if (!hasDockerfile) throw new Error('buildType dockerfile requires src/Dockerfile');
    return 'dockerfile';
  }
  if (buildType === 'node') {
    if (!(await hasStartScript(slug))) throw new Error('buildType node requires package.json with a start script');
    return 'node';
  }
  if (buildType === 'static') {
    if (!(await exists(join(srcDir(slug), 'index.html')))) throw new Error('buildType static requires src/index.html');
    return 'static';
  }
  if (hasDockerfile) return 'dockerfile';
  if (await hasStartScript(slug)) return 'node';
  if (await exists(join(srcDir(slug), 'index.html'))) return 'static';
  throw new Error('no build strategy detected (need Dockerfile, package.json with start script, or index.html)');
};

// ---- pipeline

class DeployLog {
  constructor(private readonly id: string) {}

  private line(text: string): void {
    void appendFile(logPath(this.id), `${text}\n`, 'utf8').catch(() => undefined);
    emit(this.id, { type: 'log', line: text });
  }

  cmd(header: string): void {
    this.line(`$ ${header}`);
  }

  raw(text: string): void {
    this.line(text);
  }
}

const tailOf = (value: string): string => value.split('\n').slice(-5).join('\n');

// 07 §4.4 — regenerated on every deployment, never patched
const writeEnvFile = async (slug: string, appId: string): Promise<void> => {
  const rows = await EnvVars.findAll({ where: { appId }, order: [['key', 'ASC']] });
  const text = rows.map((r) => `${r.key}=${decrypt(r.valueEnc)}`).join('\n');
  await mkdir(appDir(slug), { recursive: true });
  await writeFile(join(appDir(slug), '.env'), text ? `${text}\n` : '', { mode: 0o600 });
};

// 07 §6 — 2 s polling, healthy/unhealthy terminate early, `starting` runs out the clock.
// The semaphore is already released here (07 §2: health polling never holds a slot).
const pollHealth = async (slug: string, log: DeployLog): Promise<string> => {
  const t0 = Date.now();
  let status = await appHealth(slug);
  while (status !== 'healthy' && status !== 'unhealthy' && Date.now() - t0 < config.deployTimeoutSeconds * 1000) {
    await new Promise((r) => setTimeout(r, 2000));
    status = await appHealth(slug);
  }
  if (status === 'healthy') log.raw(`[health] healthy after ${Math.round((Date.now() - t0) / 1000)}s`);
  return status;
};

export const runDeployment = async (appId: string, deploymentId: string): Promise<void> => {
  const [d, app] = await Promise.all([Deployments.findByPk(deploymentId), Apps.findByPk(appId)]);
  if (!d || !app) return; // app torn down while queued
  if (d.status !== 'queued') return; // stale row (boot recovery marks these failed) — never re-run

  const log = new DeployLog(deploymentId);
  await mkdir(dirname(logPath(deploymentId)), { recursive: true });

  const setStatus = async (status: DeploymentInstance['status']): Promise<void> => {
    const patch: Record<string, unknown> = { status };
    if (status === 'fetching') patch.startedAt = new Date();
    await d.update(patch); // every transition lands on the row immediately (07 §1)
    emit(deploymentId, { type: 'status', status });
  };

  const fail = async (error: string): Promise<void> => {
    log.raw(`error: ${error}`);
    await d.update({ status: 'failed', error, finishedAt: new Date() });
    emit(deploymentId, { type: 'status', status: 'failed' });
    await event('deploy.failed', { targetType: 'deployment', targetId: deploymentId }, { error });
  };

  const pat = app.accessTokenEnc ? decrypt(app.accessTokenEnc) : null;
  const redact = pat ? [pat] : [];
  const shaPinned = d.commitSha !== HEAD_SHA ? d.commitSha : null;

  try {
    await setStatus('fetching');
    const first = !(await exists(join(srcDir(app.slug), '.git')));
    const url = `https://${pat ? 'x-access-token:[REDACTED]@' : ''}github.com/${app.repoOwner}/${app.repoName}.git`;
    log.cmd(first ? `git clone --depth 1 --branch ${app.branch} ${url} src` : `git -C src fetch --depth 1 origin ${shaPinned ?? app.branch}`);
    const meta = await fetchSource(
      { slug: app.slug, repoOwner: app.repoOwner, repoName: app.repoName, branch: app.branch },
      pat,
      shaPinned,
      { onLine: (line) => log.raw(line) },
    );
    await d.update({ commitSha: meta.sha, commitMessage: meta.message, author: meta.author });

    const kind = await resolveBuild(app.slug, app.buildType);
    log.raw(`[build] ${kind === 'dockerfile' ? 'repo Dockerfile' : `generated Dockerfile.swim (${kind})`}`);
    if (kind !== 'dockerfile') {
      await writeFile(join(appDir(app.slug), 'Dockerfile.swim'), renderDockerfile(kind, app.port), 'utf8');
      if (kind === 'static') {
        await mkdir(join(appDir(app.slug), '.swim'), { recursive: true });
        await writeFile(join(appDir(app.slug), '.swim', 'nginx.conf'), renderStaticNginxConf(app.port), 'utf8');
      }
    }
    await writeEnvFile(app.slug, app.id);
    await writeCompose({
      slug: app.slug,
      sha8: meta.sha.slice(0, 8),
      port: app.port,
      healthcheckPath: app.healthcheckPath,
      buildType: kind === 'dockerfile' ? 'dockerfile' : 'auto',
    });

    const release = await acquireBuildSlot(); // 07 §2: slot spans build → up -d only
    try {
      await setStatus('building');
      log.cmd(`docker compose -p swim-app-${app.slug} -f ${appDir(app.slug)}/compose.yaml build`);
      const build = await compose(app.slug, ['build'], { onLine: (line) => log.raw(line), redact });
      if (build.code !== 0) {
        log.raw(`exit code ${build.code}`);
        throw new Error(`compose build failed (exit ${build.code}):\n${tailOf(build.output)}`);
      }
      await setStatus('deploying');
      log.cmd(`docker compose -p swim-app-${app.slug} -f ${appDir(app.slug)}/compose.yaml up -d`);
      const up = await compose(app.slug, ['up', '-d'], { onLine: (line) => log.raw(line), redact });
      if (up.code !== 0) {
        log.raw(`exit code ${up.code}`);
        throw new Error(`compose up failed (exit ${up.code}):\n${tailOf(up.output)}`);
      }
    } finally {
      release();
    }

    const health = await pollHealth(app.slug, log);
    if (health !== 'healthy') {
      await fail(`container did not become healthy within ${config.deployTimeoutSeconds}s (status: ${health})`);
      return; // failed container stays up for debugging (07 §6)
    }

    await setStatus('live');
    await d.update({ finishedAt: new Date() });
    await app.update({ currentDeploymentId: d.id, status: 'live' });
    await event('deploy.live', { targetType: 'deployment', targetId: d.id }, { sha: d.commitSha });
    emit(deploymentId, { type: 'done', status: 'live' });
  } catch (err) {
    await fail(tailOf(err instanceof Error ? err.message : String(err)));
    emit(deploymentId, { type: 'done', status: 'failed' });
  } finally {
    listeners.delete(deploymentId);
  }
};
